// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime, uint256 warpTo) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1 ether);
        warpTo = bound(warpTo, 1, 2 ** 100);
        vm.warp(warpTo);
        vm.assume(unlockTime != block.timestamp);

        vm.deal(actor, amount);
        vm.prank(actor);
        try c.Put{value: amount}(unlockTime) {
            (uint256 storedUnlockTime,) = c.Acc(actor);
            uint256 expected = unlockTime > block.timestamp ? unlockTime : block.timestamp;
            assertTrue(storedUnlockTime == expected && storedUnlockTime >= block.timestamp);
        } catch {
            assertTrue(true);
        }
    }
}
